"use client";
import { Suspense, useEffect, useMemo, useRef, useState } from "react";
import * as THREE from "three";
import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { createGlass, createDunkBiscuit, createDrops, shadowed, GLASS, PLATE_Y, type BiscuitKind } from "@/lib/story/models";
import { studioEnvironment, studioLights } from "@/lib/story/studio";
import { fontsReady } from "@/lib/story/print";
import { clamp, lerp } from "@/lib/utils";
import type { DunkId } from "@/data/site";

export type DunkSceneProps = {
  biscuitId: DunkId;
  /** state: 'idle' | 'dunking' | 'safe' | 'broken' */
  state: "idle" | "dunking" | "safe" | "broken";
  /** elapsed seconds dunked */
  elapsed: number;
  /** max survival limit */
  limit: number;
};

const BASE = -0.55;
const SURF = BASE + GLASS.LEVEL_MAX;

function DunkRig({ biscuitId, state, elapsed, limit }: DunkSceneProps) {
  const { camera, gl, scene } = useThree();
  const cam = camera as THREE.PerspectiveCamera;

  const lights = useMemo(() => studioLights({ shadows: true, reach: 3, mapSize: 1024 }), []);
  useEffect(() => {
    scene.environment = studioEnvironment(gl);
    scene.environmentIntensity = 0.95;
    scene.add(lights);
    return () => { scene.remove(lights); };
  }, [gl, scene, lights]);

  const glass = useMemo(() => {
    const g = createGlass();
    g.root.position.set(0, BASE, 0);
    g.setLevel(0.85);
    return g;
  }, []);

  const biscuits = useMemo(() => {
    const map = new Map<DunkId, ReturnType<typeof createDunkBiscuit>>();
    const kinds: DunkId[] = ["glucose", "rusk", "osmania", "nankhatai"];
    kinds.forEach((k) => {
      const b = createDunkBiscuit(k as BiscuitKind);
      b.root.visible = false;
      map.set(k, b);
    });
    return map;
  }, []);

  const splash = useMemo(() => createDrops(16), []);
  const floor = useMemo(() => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(8, 8), new THREE.ShadowMaterial({ opacity: 0.22, color: "#3a1d0a" }));
    m.rotation.x = -Math.PI / 2;
    m.position.y = BASE;
    m.receiveShadow = true;
    return m;
  }, []);

  const curB = biscuits.get(biscuitId)!;
  const breakTime = useRef(0);

  useEffect(() => {
    biscuits.forEach((b, k) => {
      b.root.visible = k === biscuitId;
    });
  }, [biscuitId, biscuits]);

  useEffect(() => {
    if (state === "broken") {
      breakTime.current = performance.now();
    }
  }, [state]);

  useFrame((st) => {
    const t = st.clock.elapsedTime;
    glass.chai.uTime.value = t;

    const hoverY = BASE + GLASS.H + 0.35 + curB.half;
    const dunkY = SURF - 0.38 + curB.half;

    let targetY = hoverY;
    let split = false;
    let soak = -99;

    if (state === "dunking") {
      const p = Math.min(1, elapsed / 0.4);
      targetY = lerp(hoverY, dunkY, p);
      soak = Math.min(SURF - targetY, SURF - dunkY) + (elapsed / limit) * 0.15;
      curB.set({ soak, split: false, wet: 1 });
      glass.chai.uSlosh.value = Math.sin(t * 10) * 0.08;
    } else if (state === "safe") {
      targetY = hoverY;
      soak = 0.25;
      curB.set({ soak, split: false, wet: 0.85 });
      glass.chai.uSlosh.value = 0;
    } else if (state === "broken") {
      targetY = hoverY - 0.15;
      split = true;
      const brokenElapsed = (performance.now() - breakTime.current) / 1000;
      const dropK = clamp(brokenElapsed / 0.35);
      curB.set({ soak: 0.4, split: true, wet: 1 });
      curB.hinge.rotation.x = dropK * 1.8;
      curB.hinge.position.y = -curB.half * 0.16 - dropK * dropK * 2.5;
      curB.hinge.position.z = dropK * 0.15;
      curB.hinge.visible = curB.root.position.y + curB.hinge.position.y > SURF - 0.2;

      if (brokenElapsed < 0.6) {
        splash.burst(new THREE.Vector3(0, SURF + 0.02, 0), brokenElapsed / 0.6, 0.7, 12);
      } else {
        splash.mesh.visible = false;
      }
      glass.chai.uSlosh.value = Math.sin(brokenElapsed * 20) * 0.25 * (1 - dropK);
    } else {
      // idle
      targetY = hoverY + Math.sin(t * 2) * 0.03;
      curB.set({ soak: -99, split: false, wet: 1 });
      curB.hinge.rotation.x = 0;
      curB.hinge.position.set(0, -curB.half * 0.16, 0);
      curB.hinge.visible = true;
      glass.chai.uSlosh.value = 0;
      splash.mesh.visible = false;
    }

    curB.root.position.y += (targetY - curB.root.position.y) * 0.15;
    curB.root.rotation.set(-0.06, Math.sin(t * 0.8) * 0.08 - 0.3, 0);
  });

  return (
    <>
      <primitive object={floor} />
      <primitive object={glass.root} />
      {Array.from(biscuits.values()).map((b, idx) => (
        <primitive key={idx} object={b.root} />
      ))}
      <primitive object={splash.mesh} />
    </>
  );
}

export default function DunkScene(props: DunkSceneProps) {
  const [fonts, setFonts] = useState(false);
  useEffect(() => {
    fontsReady().then(() => setFonts(true));
  }, []);

  return (
    <div className="relative h-full w-full">
      {fonts && (
        <Canvas
          shadows
          dpr={[1, 1.5]}
          camera={{ fov: 25, position: [0, 0.4, 4.4], near: 0.1, far: 40 }}
          gl={{ antialias: true, alpha: true, powerPreference: "high-performance", toneMapping: THREE.NeutralToneMapping, toneMappingExposure: 1.0 }}
          className="!absolute inset-0"
          aria-hidden
        >
          <Suspense fallback={null}>
            <DunkRig {...props} />
          </Suspense>
        </Canvas>
      )}
    </div>
  );
}
