import Link from "next/link";
import { cn } from "@/lib/utils";

type ButtonProps = {
  href: string;
  variant?: "ink" | "ivory" | "ghost" | "ghost-light";
  size?: "md" | "lg";
  className?: string;
  children: React.ReactNode;
};

const Arrow = () => (
  <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden className="transition-transform duration-500 group-hover:translate-x-1">
    <path d="M1 7h11M7 1l6 6-6 6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

export default function Button({ href, variant = "ink", size = "md", className, children }: ButtonProps) {
  const base = "group inline-flex items-center gap-3 font-body font-medium tracking-[0.02em] rounded-full transition-all duration-500";
  const sizes = { md: "px-6 py-3 text-[0.85rem]", lg: "px-8 py-4 text-[0.95rem]" };
  const variants = {
    ink: "bg-ink text-ivory hover:bg-accent",
    ivory: "bg-ivory text-ink hover:bg-white hover:shadow-md hover:-translate-y-px",
    ghost: "border border-ink/20 text-ink hover:border-ink",
    "ghost-light": "border border-ivory/30 text-ivory hover:border-ivory",
  };
  const cls = cn(base, sizes[size], variants[variant], className);
  const isExt = href.startsWith("http") || href.startsWith("mailto:") || href.startsWith("tel:");

  const inner = <>{children}<Arrow /></>;

  if (isExt) return <a href={href} className={cls} data-cursor="cta">{inner}</a>;
  return <Link href={href} className={cls} data-cursor="cta">{inner}</Link>;
}
