"use client";
import { useState, useRef, useEffect } from "react";
import { dunkables, type DunkId, type Dunkable } from "@/data/site";
import DunkScene from "@/components/story/DunkScene";
import Reveal from "@/components/motion/Reveal";
import { cn } from "@/lib/utils";

export default function DunkSection() {
  const [selected, setSelected] = useState<DunkId>("glucose");
  const [state, setState] = useState<"idle" | "dunking" | "safe" | "broken">("idle");
  const [elapsed, setElapsed] = useState(0);
  const [result, setResult] = useState<string | null>(null);
  const [bests, setBests] = useState<Partial<Record<DunkId, number>>>({});

  const curDunkable = dunkables.find((d) => d.id === selected) || dunkables[0];
  const timerRef = useRef<number | null>(null);
  const startRef = useRef(0);

  // Load personal bests
  useEffect(() => {
    try {
      const stored = localStorage.getItem("tapri:dunk:bests");
      if (stored) setBests(JSON.parse(stored));
    } catch { /* storage not available */ }
  }, []);

  const handleStart = (e: React.SyntheticEvent) => {
    e.preventDefault();
    if (state === "broken") {
      setState("idle");
      setElapsed(0);
      setResult(null);
      return;
    }
    setState("dunking");
    setResult(null);
    startRef.current = performance.now();

    const tick = () => {
      const now = performance.now();
      const sec = (now - startRef.current) / 1000;
      setElapsed(sec);

      if (sec >= curDunkable.limit) {
        setState("broken");
        setResult("SNAP! Broken into the chai. We’ll bring a spoon.");
        if (timerRef.current) cancelAnimationFrame(timerRef.current);
        return;
      }
      timerRef.current = requestAnimationFrame(tick);
    };
    timerRef.current = requestAnimationFrame(tick);
  };

  const handleEnd = () => {
    if (state !== "dunking") return;
    if (timerRef.current) cancelAnimationFrame(timerRef.current);

    const time = elapsed;
    const [min, max] = curDunkable.sweet;

    if (time >= min && time <= max) {
      setState("safe");
      const currentBest = bests[selected];
      const mid = (min + max) / 2;
      const isNewBest = !currentBest || Math.abs(time - mid) < Math.abs(currentBest - mid);

      if (isNewBest) {
        const nextBests = { ...bests, [selected]: Number(time.toFixed(1)) };
        setBests(nextBests);
        try { localStorage.setItem("tapri:dunk:bests", JSON.stringify(nextBests)); } catch { /* ignore */ }
        setResult(`NEW PERSONAL BEST! (${time.toFixed(1)}s) ★ Malty, warm, holds its spine.`);
      } else {
        setResult(`PERFECT DUNK! (${time.toFixed(1)}s) Malty, warm, holds its spine.`);
      }
    } else if (time < min) {
      setState("safe");
      setResult(`Under-dunked (${time.toFixed(1)}s). Still bone-dry inside.`);
    } else {
      setState("broken");
      setResult(`Four seconds! Saturated and dropped to the bottom.`);
    }
  };

  const handleReset = () => {
    if (timerRef.current) cancelAnimationFrame(timerRef.current);
    setState("idle");
    setElapsed(0);
    setResult(null);
  };

  useEffect(() => {
    handleReset();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected]);

  return (
    <section id="dunk" className="relative bg-deep text-ivory py-28 md:py-36" data-theme="dark">
      <div className="container-x">
        {/* Header */}
        <div className="max-w-3xl">
          <p className="eyebrow !text-ivory/50">The dunk test</p>
          <Reveal as="h2" className="fat text-[clamp(2.6rem,7vw,5.5rem)] leading-none text-ivory">
            Hold to dunk. <span className="text-kesar italic font-normal">Let go in time.</span>
          </Reveal>
          <p className="body-sm mt-4 text-ivory/70 max-w-xl">
            A physics test of structural integrity. Every biscuit has a precise sweet spot before the matrix dissolves. Pick your biscuit, press and hold the button, and release before it collapses.
          </p>
        </div>

        {/* Game Layout */}
        <div className="mt-14 grid grid-cols-12 gap-8 lg:gap-12 items-center">
          {/* Controls & Biscuit Selector */}
          <div className="col-span-12 lg:col-span-5 space-y-6">
            {/* Biscuit picker tabs */}
            <div className="grid grid-cols-2 gap-3">
              {dunkables.map((d) => (
                <button
                  key={d.id}
                  onClick={() => { setSelected(d.id); }}
                  className={cn(
                    "flex flex-col p-4 rounded-xl text-left border transition-all duration-300",
                    selected === d.id
                      ? "border-kesar bg-kesar/15 text-ivory shadow-lg"
                      : "border-ivory/15 bg-white/5 text-ivory/60 hover:border-ivory/40 hover:text-ivory"
                  )}
                  data-cursor="link"
                >
                  <span className="font-mono text-[0.6rem] uppercase tracking-wider text-kesar">{d.sub}</span>
                  <span className="fat text-xl mt-1">{d.name}</span>
                  <span className="font-mono text-[0.62rem] mt-2 opacity-70">Limit: {d.limit}s</span>
                </button>
              ))}
            </div>

            {/* Note about selected biscuit */}
            <div className="rounded-xl border border-ivory/10 bg-white/5 p-4 text-sm text-ivory/70">
              <span className="font-mono text-[0.6rem] uppercase text-kesar tracking-wider block mb-1">Baker’s Note:</span>
              {curDunkable.note}
            </div>

            {/* Timer readout */}
            <div className="flex items-baseline justify-between border-y border-ivory/15 py-4">
              <div className="flex items-center gap-3">
                <span className="font-mono text-xs uppercase tracking-widest text-ivory/60">Timer</span>
                {bests[selected] && (
                  <span className="rounded-full bg-kesar/20 px-2.5 py-0.5 font-mono text-[0.6rem] font-bold text-kesar border border-kesar/30">
                    ★ Best: {bests[selected]}s
                  </span>
                )}
              </div>
              <div className="flex items-baseline gap-1 font-mono">
                <span className={cn("text-5xl font-bold tabular-nums", state === "broken" ? "text-accent" : state === "safe" ? "text-leaf" : "text-ivory")}>
                  {elapsed.toFixed(1)}
                </span>
                <span className="text-xl text-ivory/50">s</span>
              </div>
            </div>

            {/* The Hold-to-dunk Button */}
            <div className="pt-2">
              <button
                type="button"
                onMouseDown={handleStart}
                onMouseUp={handleEnd}
                onMouseLeave={handleEnd}
                onTouchStart={handleStart}
                onTouchEnd={handleEnd}
                onTouchCancel={handleEnd}
                data-cursor="cta"
                className={cn(
                  "tapri-hold w-full rounded-full py-5 text-center font-body text-base font-bold uppercase tracking-widest shadow-2xl transition-all duration-300 select-none",
                  state === "dunking"
                    ? "bg-accent scale-95 text-white ring-4 ring-accent/40"
                    : state === "broken"
                    ? "bg-paper text-ink hover:bg-ivory"
                    : "bg-kesar text-ink hover:bg-kesar/90 hover:scale-[1.02]"
                )}
              >
                {state === "dunking" ? "HOLDING... RELEASE TO LIFT!" : state === "broken" ? "TRY AGAIN (TAP)" : "PRESS & HOLD TO DUNK"}
              </button>
            </div>

            {/* Result Message Banner */}
            {result && (
              <div
                className={cn(
                  "rounded-xl p-4 text-center font-mono text-xs font-semibold uppercase tracking-wider animate-[tapri-still-in_0.4s_ease-out]",
                  state === "broken" ? "bg-accent/20 text-accent border border-accent/40" : "bg-leaf/20 text-pista border border-leaf/40"
                )}
              >
                {result}
              </div>
            )}
          </div>

          {/* 3D Live Dunk Canvas */}
          <div className="col-span-12 lg:col-span-7 aspect-[4/3] rounded-3xl overflow-hidden bg-black/30 border border-ivory/10 shadow-inner relative">
            <DunkScene biscuitId={selected} state={state} elapsed={elapsed} limit={curDunkable.limit} />

            {/* Safe window indicator bar */}
            <div className="absolute bottom-4 left-6 right-6 flex items-center justify-between font-mono text-[0.6rem] text-ivory/50 bg-deep/80 backdrop-blur-sm px-4 py-2 rounded-full border border-ivory/10">
              <span>Target: {curDunkable.sweet[0]}s – {curDunkable.sweet[1]}s</span>
              <span className="text-kesar font-semibold">Max: {curDunkable.limit}s</span>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
